def _slot_from(
    hass: HomeAssistant, config_entry: ConfigEntry, msg: dict[str, Any]
) -> int:
    """
    Resolve the slot a message means, however it chose to say it.

    An entity id is the steadiest of the three and what a stored card should
    hold; a name is what a person writes; a slot number is what everything
    below this line still keys on. Resolution happens here because this is
    the boundary where those vocabularies meet.
    """
    if entity_id := msg.get(ATTR_USER_ENTITY_ID):
        # The steadiest handle there is. An entity id is unique by
        # construction, and this integration's own never move when a user is
        # renamed -- unique IDs keep the slot number, which is the whole
        # reason a rename costs nothing. A card holding one goes on working
        # through renames that would strand a card holding a name.
        entity = er.async_get(hass).async_get(entity_id)
        if entity is None:
            raise ServiceValidationError(f"No entity {entity_id!r}")
        slot = parse_slot_unique_id(config_entry.entry_id, entity.unique_id)
        if slot is None:
            raise ServiceValidationError(
                f"{entity_id!r} does not belong to a user in this config entry"
            )
        return slot
    if (slot := msg.get(ATTR_SLOT)) is not None:
        return slot
    if not (name := msg.get(CONF_NAME)):
        raise ServiceValidationError("No entity, name or slot provided")

    # Matched slugified, the way a config entry title is, so a caller that
    # has only the slug an entity id was built from can still name its user.
    config = get_entry_config(config_entry)
    wanted = slugify(name)
    matches = [known for known in config.users if slugify(known) == wanted]
    if not matches:
        raise ServiceValidationError(f"No user named {name!r} in this config entry")
    if len(matches) > 1:
        # Slugifying collapses more than the name rules do -- "Ada-Lovelace"
        # and "Ada Lovelace" are two users but one slug. Picking either would
        # write somebody else's credential.
        raise ServiceValidationError(
            f"{name!r} matches more than one user in this config entry: "
            f"{', '.join(sorted(matches))}"
        )
    if (resolved := config.assignment.slot(matches[0])) is None:
        # A user can exist in the configuration without a number, while
        # allocation is still deciding where they go. There is nothing on any
        # lock to address yet.
        raise ServiceValidationError(f"{matches[0]!r} has not been given a slot yet")
    return resolved


def _get_slot_condition_entity_id(
    config_entry: ConfigEntry, slot_num: int
) -> str | None:
    """Get condition entity ID from slot config."""
    return get_entry_config(config_entry).slot(slot_num).get(CONF_CONDITION)

    return True


@websocket_api.websocket_command(
    {
        vol.Required("type"): "lock_code_manager/get_config_entry_data",
        vol.Exclusive("config_entry_title", "entry"): str,
        vol.Exclusive("config_entry_id", "entry"): str,
    }
)
@websocket_api.async_response
@async_get_entry
async def get_config_entry_data(
    hass: HomeAssistant,
    connection: websocket_api.ActiveConnection,
    msg: dict[str, Any],
    config_entry: ConfigEntry,
) -> None:
    """Return the config entry fragment, entity registry entries, lock list, and slot calendar mapping."""
    entry_locks = config_entry.runtime_data.locks
    entry_config = get_entry_config(config_entry)

    connection.send_result(
        msg["id"],
        {
            CONF_CONFIG_ENTRY: config_entry.as_json_fragment,
            CONF_ENTITIES: [
                entity.as_partial_dict
                for entity in er.async_entries_for_config_entry(
                    er.async_get(hass), config_entry.entry_id
                )
            ],
            CONF_LOCKS: [
                {
                    ATTR_ENTITY_ID: lock_id,
                    CONF_NAME: _get_lock_friendly_name(hass, lock),
                }
                for lock_id, lock in entry_locks.items()
            ],
            # Still keyed by slot, because that is what entity unique IDs
            # carry and the card joins the two on it. The NAME travels with
            # it so the card never has to work out who a slot belongs to:
            # a dashboard strategy builds configuration, and entity states
            # are not reliably populated while it runs.
            CONF_SLOTS: {
                slot_num: {
                    CONF_NAME: entry_config.name_for(slot_num),
                    CONF_CONDITION: slot.get(CONF_CONDITION),
                }
                for slot_num, slot in entry_config.slots.items()
            },
        },
    )


def _serialize_slot(
    slot: Any,
    code: str | SlotCode | None,
    *,
    reveal: bool,
    name: str | None = None,
    managed: bool | None = None,
    in_sync: bool | None = None,
    configured_code: str | None = None,
    active: bool | None = None,
    enabled: bool | None = None,
    config_entry_id: str | None = None,
    config_entry_title: str | None = None,
) -> dict[str, Any]:
    """Serialize a slot dict, masking the code unless ``reveal`` is True."""
    result: dict[str, Any] = {ATTR_SLOT: slot}
    if name:
        result[CONF_NAME] = name
    if managed is not None:
        result[ATTR_MANAGED] = managed
    if in_sync is not None:
        result[ATTR_IN_SYNC] = in_sync
    if active is not None:
        result[ATTR_ACTIVE] = active
    if enabled is not None:
        result[CONF_ENABLED] = enabled
    if config_entry_id:
        result[ATTR_CONFIG_ENTRY_ID] = config_entry_id
    if config_entry_title:
        result[ATTR_CONFIG_ENTRY_TITLE] = config_entry_title

    # Serialize code (SlotCode sentinels, masking, and length) via shared helper.
    result.update(_slot_code_payload(code, reveal=reveal))

    # Configured code from LCM (desired state) - always include for managed slots
    if configured_code is not None:
        if reveal:
            result[ATTR_CONFIGURED_CODE] = configured_code
        else:
            result[ATTR_CONFIGURED_CODE_LENGTH] = len(configured_code)
    # Fall back to entity registry name/original_name
    return lock.display_name


def _serialize_lock_coordinator(
    hass: HomeAssistant, lock: BaseLock, *, reveal: bool = False
) -> dict[str, Any]:
    """Serialize what the lock holds, as its worker knows it."""
    data = lock_codes(hass, lock.lock.entity_id)
    managed_slots = slots_configured_on(hass, lock.lock.entity_id)
    slot_entity_ids = _get_slot_entity_ids(hass, lock.lock.entity_id)
    slot_metadata = _get_slot_metadata(hass, slot_entity_ids)
    ent_reg = er.async_get(hass)

    slots = []
    for slot, code in sorted(data.items()):
        meta = slot_metadata.get(slot)
        slot_ids = slot_entity_ids.get(slot)
        entry_id = slot_ids.config_entry_id if slot_ids else None
        entry_title = None
        in_sync = None
        if entry_id:
            entry = hass.config_entries.async_get_entry(entry_id)
            entry_title = entry.title if entry else None
            in_sync = _get_bool_state(
                hass,
                _in_sync_entity_id(ent_reg, entry_id, slot, lock.lock.entity_id),
            )
        slots.append(
            _serialize_slot(
                slot,
                code,
                reveal=reveal,
                name=meta.name if meta else None,
                managed=slot in managed_slots,
                in_sync=in_sync,
                configured_code=meta.configured_pin if meta else None,
                active=meta.active if meta else None,
                enabled=meta.enabled if meta else None,
                config_entry_id=entry_id,
                config_entry_title=entry_title,
            )
        )

    result: dict[str, Any] = {
        ATTR_LOCK_ENTITY_ID: lock.lock.entity_id,
        ATTR_LOCK_NAME: _get_lock_friendly_name(hass, lock),
        CONF_SLOTS: slots,
    }
    if lock_reachable(hass, lock.lock.entity_id) is False:
        result[ATTR_SYNC_STATUS] = "suspended"
    return result


@websocket_api.websocket_command(
    {
        vol.Required("type"): "lock_code_manager/subscribe_lock_codes",
        vol.Required(ATTR_LOCK_ENTITY_ID): str,
        vol.Optional("reveal", default=False): bool,
    }
)
@websocket_api.async_response
async def subscribe_lock_codes(
    hass: HomeAssistant,
    connection: websocket_api.ActiveConnection,
    msg: dict[str, Any],
) -> None:
    """
    Subscribe to the lock's codes and LCM entity state updates for a lock.

    Triggers updates when:
    - The lock's worker learns of a change (codes on lock)
    - LCM entity states change (enabled, active, name, configured PIN)
    """
    lock_entity_id = msg[ATTR_LOCK_ENTITY_ID]
    reveal = msg["reveal"]
    lock = get_managed_locks(hass).get(lock_entity_id)
    if not lock:
        connection.send_error(
            msg["id"],
            websocket_api.const.ERR_NOT_FOUND,
            f"Lock {lock_entity_id} is not managed by Lock Code Manager",
        )
        return

    @callback
    def _send_update() -> None:
        connection.send_event(
            msg["id"], _serialize_lock_coordinator(hass, lock, reveal=reveal)
        )
        # Re-resolve tracked entities to pick up entities created after
        # subscription was established
        _refresh_state_tracking()

    @callback
    def _on_state_change(event: Event[EventStateChangedData]) -> None:
        """Handle Lock Code Manager entity state changes."""
        old_state = event.data.get("old_state")
        new_state = event.data.get("new_state")

        # Only send update if actual state value changed or entity created/removed
        if old_state is None or new_state is None or old_state.state != new_state.state:
            _send_update()

    # Track Lock Code Manager entity state changes (enabled, active, name, PIN)
    _refresh_state_tracking = _setup_dynamic_state_tracking(
        hass,
        lambda: set(_get_slot_state_entity_ids(hass, lock_entity_id)),
        _on_state_change,
    )
    unsub_state = _refresh_state_tracking()

    # Track what the lock's worker learns (lock code changes).
    unsub_coordinator = async_dispatcher_connect(
        hass, signal_lock_changed(lock_entity_id), _send_update
    )

    def _unsub_all() -> None:
        unsub_coordinator()
        unsub_state()

    connection.subscriptions[msg["id"]] = _unsub_all
    connection.send_result(msg["id"])
    _send_update()


