input.command:
cd /Users/raman/projects/lock_code_manager/custom_components/lock_code_manager && python3 -c "
import json
d=json.load(open('strings.json'))
for k,v in d.get('issues',{}).items():
    s=json.dumps(v)
    if 'slot' in s: print('issue',k)
for k,v in d.get('exceptions',{}).items():
    if 'slot' in json.dumps(v): print('exc',k, v)
"; grep -rn "translation_key=\|async_create_issue" --include=*.py . | grep -v __pycache__ | grep -i "slot\|issue" | head -40

