/Users/raman/.bashrc: line 2: /private/tmp/claude-501/-Users-raman/a7dfd7d7-c945-450a-b54d-0eac5add44b1/scratchpad/shell-probe.log: No such file or directory
types.ts:395:    slot_num: number;
test/mock-hass.ts:60: *         callback({ slot_num: 1, name: 'Test' });
    lockCodeManagerEntities: LockCodeManagerEntityEntry[],
    configEntryData: LockCodeManagerConfigEntryDataResponse
): SlotMapping {
    const mainEntities: LockCodeManagerEntityEntry[] = [];
    const conditionEntities: LockCodeManagerEntityEntry[] = [];
    const codeSensorEntities: LockCodeManagerEntityEntry[] = [];
    const inSyncEntities: LockCodeManagerEntityEntry[] = [];
    lockCodeManagerEntities
        .filter((entity) => entity.slotNum === slotNum)
        .forEach((entity) => {
            // A disabled row has no state to show. These two groups are
            // optional, so such a row is left out; the required rows below
            // are addressed whether or not they are disabled.
            if (entity.key === CODE_SENSOR_KEY) {
                if (!entity.disabled_by) codeSensorEntities.push(entity);
            } else if (isInSyncKey(entity.key)) {
                if (!entity.disabled_by) inSyncEntities.push(entity);
            } else if (CONDITION_KEYS.includes(entity.key)) {
                conditionEntities.push(entity);
            } else if (![ACTIVE_KEY, CODE_EVENT_KEY].includes(entity.key)) {
                mainEntities.push(entity);
            }
        });
    const codeEventEntity = lockCodeManagerEntities.find(
        (entity) => entity.slotNum === slotNum && entity.key === CODE_EVENT_KEY
    );
    const pinActiveEntity = lockCodeManagerEntities.find(
        (entity) => entity.slotNum === slotNum && entity.key === ACTIVE_KEY
    );
    const slotInfo = configEntryData.slots[slotNum];
    const calendarEntityId: string | null | undefined = slotInfo?.condition;

    return {
        calendarEntityId,
        codeEventEntity,
        codeSensorEntities,
        conditionEntities,
        inSyncEntities,
        mainEntities,
        pinActiveEntity,
        slotNum,
        userName: slotInfo?.name ?? null
    };
}

